async () => {
  const out=[];
  let doc=document;
  for(let p=1;p<=17;p++){
    if(p>1){
      const f=doc.forms[0];
      const fd=new FormData(f);
      fd.set('__EVENTTARGET','gv');fd.set('__EVENTARGUMENT','Page$'+p);
      const r=await fetch('/Devices.aspx',{method:'POST',body:new URLSearchParams(fd)});
      doc=new DOMParser().parseFromString(await r.text(),'text/html');
    }
    doc.querySelectorAll('#gv > tbody > tr').forEach(tr=>{const c=[...tr.children].map(x=>x.innerText??x.textContent);if(/^D\d+/.test((c[1]||'').trim()))out.push(p+':'+c.slice(1,4).map(s=>s.trim()).join(','))});
  }
  return out.filter(s=>/,(1004|1011|1026),/.test(s));
}

