async () => {
  const res=[],dev=[];
  async function scan(url,max,out,rx){
    const g=await (await fetch(url)).text();let doc=new DOMParser().parseFromString(g,'text/html');
    for(let p=1;p<=max;p++){
      if(p>1){const fd=new FormData(doc.forms[0]);fd.set('__EVENTTARGET','gv');fd.set('__EVENTARGUMENT','Page$'+p);
        const r=await fetch(url,{method:'POST',body:new URLSearchParams(fd)});doc=new DOMParser().parseFromString(await r.text(),'text/html');}
      doc.querySelectorAll('#gv > tbody > tr').forEach(tr=>{const c=[...tr.children].map(x=>x.textContent.trim());if(rx.test(c[1]||''))out.push(c.slice(1,4).join(','))});
    }
  }
  await scan('/Residents.aspx',12,res,/\S{3} Alder|\S/ );
  await scan('/Devices.aspx',17,dev,/^D\d+$/);
  const r=res.filter(s=>/^[A-Z][a-z]+ /.test(s)&&/,\d{4},/.test(s));
  return {residents:r.length,r1004:r.filter(s=>s.includes(',1004,')),r1011:r.filter(s=>s.includes(',1011,')),r1026:r.filter(s=>s.includes(',1026,')),devices:dev.length,d1004_1011:dev.filter(s=>/,(1004|1011),/.test(s)),d1026:dev.filter(s=>s.includes(',1026,'))};
}

